
import csv
from pathlib import Path

import matplotlib
matplotlib.use("Agg")

import matplotlib.pyplot as plt

# Set input and output locations.
input_folder = Path("integration/output/product_analysis")
output_folder = Path("visualizations/charts")
output_folder.mkdir(parents=True, exist_ok=True)

# Find the CSV file generated by Spark.
csv_files = list(input_folder.glob("part-*.csv"))

if not csv_files:
    raise FileNotFoundError("Spark integrated CSV was not found.")

# Read the integrated product data.
products = []

with csv_files[0].open(
    "r", encoding="utf-8", newline=""
) as file:
    reader = csv.DictReader(file)

    for row in reader:
        products.append({
            "product_id": row["product_id"],
            "name": row["name"],
            "views": int(row["total_views"]),
            "cart_quantity": int(row["total_cart_quantity"]),
            "completed_quantity": int(row["completed_quantity"])
        })

print("Products loaded:", len(products))


# CHART 1: TOP PRODUCTS BY BROWSING VIEWS

top_views = sorted(
    products,
    key=lambda x: x["views"],
    reverse=True
)[:10]

plt.figure(figsize=(11, 6))

plt.barh(
    [p["product_id"] for p in reversed(top_views)],
    [p["views"] for p in reversed(top_views)]
)

plt.title("Top 10 Products by Browsing Views")
plt.xlabel("Product-detail views (HBase sample)")
plt.ylabel("Product ID")
plt.tight_layout()

plt.savefig(
    output_folder / "chart1_top_views.png",
    dpi=200
)
plt.close()

print("Chart 1 saved.")


# CHART 2: TOP PRODUCTS BY CART QUANTITY

top_cart = sorted(
    products,
    key=lambda x: x["cart_quantity"],
    reverse=True
)[:10]

plt.figure(figsize=(11, 6))

plt.barh(
    [p["product_id"] for p in reversed(top_cart)],
    [p["cart_quantity"] for p in reversed(top_cart)]
)

plt.title("Top 10 Products by Cart Quantity")
plt.xlabel("Cart quantity (HBase sample)")
plt.ylabel("Product ID")
plt.tight_layout()

plt.savefig(
    output_folder / "chart2_top_cart.png",
    dpi=200
)
plt.close()

print("Chart 2 saved.")


# CHART 3: TOP PRODUCTS BY COMPLETED QUANTITY

top_completed = sorted(
    products,
    key=lambda x: x["completed_quantity"],
    reverse=True
)[:10]

plt.figure(figsize=(11, 6))

plt.barh(
    [p["product_id"] for p in reversed(top_completed)],
    [p["completed_quantity"] for p in reversed(top_completed)]
)

plt.title("Top 10 Products by Completed Transaction Quantity")
plt.xlabel("Quantity in completed transactions (MongoDB)")
plt.ylabel("Product ID")
plt.tight_layout()

plt.savefig(
    output_folder / "chart3_completed_quantity.png",
    dpi=200
)
plt.close()

print("Chart 3 saved.")


# CHART 4: BROWSING VS COMPLETED QUANTITY

# Use products with at least one browsing view.
active_products = [
    p for p in products if p["views"] > 0
]

plt.figure(figsize=(10, 6))

plt.scatter(
    [p["views"] for p in active_products],
    [p["completed_quantity"] for p in active_products],
    alpha=0.4
)

plt.title("Browsing Views vs Completed Transaction Quantity")
plt.xlabel("Views (HBase 5,000-session sample)")
plt.ylabel("Completed quantity (MongoDB transactions)")

plt.figtext(
    0.5, 0.01,
    "Different source coverage; not a conversion rate.",
    ha="center",
    fontsize=9
)

plt.tight_layout(rect=[0, 0.04, 1, 1])

plt.savefig(
    output_folder / "chart4_views_vs_completed.png",
    dpi=200
)
plt.close()

print("Chart 4 saved.")

print("\nAll four charts created successfully.")
print("Output folder:", output_folder)
